/**
 * @event
 * @name scwin.grd_keywrdMappList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_keywrdMappList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_keywrdMappList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_keywrdMappList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.fn_removeKeywrd === 'function') { scwin.fn_removeKeywrd(r["keywrdNo"], r["keywrdNm"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fn_removeKeywrd (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fn_removeKeywrd'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_keywrdMappList.oncellclick' });
    }
};

