/**
 * @event
 * @name scwin.__on_enter_1_ipt_formatKeywrd
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__on_enter_1_ipt_formatKeywrd = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __on_enter_1_ipt_formatKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(($c.util.getKeyCode(ev))==13){ scwin.fn_searchIntegSrch() }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75100.__on_enter_1_ipt_formatKeywrd' }); }
};

/**
 * @method
 * @name scwin.searchKey
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchKey = function () {
    /* sdd-asis-lifecycle:begin fn_searchKey — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        scwin.fn_searchKeywrdListDtl();
        $('.sort a').removeClass('active');
        (($c.util.getComponent('all')) && ($c.util.getComponent('all')).addClass ? ($c.util.getComponent('all')).addClass('active') : console.error('[sdd] addClass 미지원 컴포넌트: all'));
    }
    /* sdd-asis-lifecycle:end */
};


