*/
scwin.setKeywrd = function (keywrd) {
    /* sdd-asis-lifecycle:begin fn_SetKeywrd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_formatKeywrd').setValue(keywrd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clickKeyword
 * @author Inswave
 * @date 2026. 09. 29
 * @param ele
 * @returns
 * @hidden N
*/
scwin.clickKeyword = function (ele) {
    /* sdd-asis-lifecycle:begin clickKeyword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('.sort a').on('click', function() {
            if ($(this).hasClass('active')) {
                return false;
            }
            $('.sort a').removeClass('active');
            $(this).addClass('active');
    });
    /* sdd-asis-lifecycle:end */
};


